'use server'

import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const currentPreference = cookieStore.get('notifications')?.value === 'true'

  // Toggle the preference
  const newPreference = !currentPreference

  // Save the new preference
  cookieStore.set('notifications', String(newPreference))

  // Refresh the current page to show updated state
  refresh()
}

import { toggleNotifications } from './actions'
import { cookies } from 'next/headers'

export default async function Home() {
  const cookieStore = await cookies()
  const notifications = cookieStore.get('notifications')?.value === 'true'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently: <strong>{notifications ? 'ON' : 'OFF'}</strong></p>
      <form action={toggleNotifications}>
        <button type="submit">Toggle Notifications</button>
      </form>
    </main>
  );
}
